-- Job sites read with JobSpy (chunk 3.6, ADR 0011): one source per site,
-- each off until the owner switches it on (the sites' terms don't allow
-- automated reading; KL-27). Searches rotate daily through terms x places.
-- Tested 2026-11-27: LinkedIn, Indeed, Glassdoor and Naukri answered;
-- Google Jobs (no data), Bayt (timed out) and ZipRecruiter (blocked) are
-- left out.

insert into public.job_sources (id, name, kind, enabled, notes, config) values
  ('linkedin', 'LinkedIn', 'scraper', false, 'Reads LinkedIn''s public job search (no login) with JobSpy, 30 searches a run. Off by default: LinkedIn''s terms don''t allow automated reading; switch on only if the owner accepts that (KL-27).',
